<template><AppPage title="Overview" subtitle="Operational health and recent infrastructure activity"><template #actions><v-btn to="/machines/new" color="primary" prepend-icon="mdi-plus">Create machine</v-btn></template>
  <v-alert :type="ui.connectionState==='connected'?'success':ui.connectionState==='checking'?'info':'error'" variant="tonal" class="mb-6" :icon="false"><div class="health-strip"><div><strong>API {{ connectionCopy }}</strong><span>Namespace {{ ns.active }}</span></div><div><strong>{{ attention.length }}</strong><span>need attention</span></div><div><strong>{{ pending.length }}</strong><span>in progress</span></div><div><strong>{{ ui.lastRefreshAt ? ui.lastRefreshAt.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}) : '—' }}</strong><span>last refresh</span></div></div></v-alert>
  <div class="summary-grid mb-6"><router-link v-for="item in summaries" :key="item.label" :to="item.to" class="summary"><v-icon :icon="item.icon" color="primary"/><span>{{ item.label }}</span><strong>{{ item.count }}</strong></router-link></div>
  <v-row><v-col cols="12" lg="7"><v-card variant="outlined"><v-card-title>Needs attention</v-card-title><v-list v-if="attention.length" lines="two"><v-list-item v-for="item in attention" :key="item.to" :to="item.to" :title="item.name" :subtitle="item.kind"><template #append><StatusBadge :state="item.status"/></template></v-list-item></v-list><EmptyState v-else title="No resources need attention" message="Warning and error states will appear here." icon="mdi-check-circle-outline"/></v-card></v-col>
  <v-col cols="12" lg="5"><v-card variant="outlined"><v-card-title>Recent resources</v-card-title><v-list v-if="recent.length" lines="two"><v-list-item v-for="item in recent" :key="item.to" :to="item.to" :title="item.name" :subtitle="`${item.kind} · ${relativeTime(item.createdAt)}`"><template #prepend><v-icon :icon="item.icon"/></template></v-list-item></v-list><EmptyState v-else title="No recent resources" message="Created resources with timestamps will appear here."/></v-card></v-col></v-row>
</AppPage></template>
<script setup lang="ts">
import { computed } from 'vue'
import AppPage from '@/components/app/AppPage.vue'; import StatusBadge from '@/components/common/StatusBadge.vue'; import EmptyState from '@/components/feedback/EmptyState.vue'; import { relativeTime } from '@/composables/useTime'; import { classifyStatus } from '@/lib/status'
import { useUIStore } from '@/stores/ui'; import { useNamespaceStore } from '@/stores/namespace'; import { useMachinesStore } from '@/stores/machines'; import { useVolumesStore } from '@/stores/volumes'; import { useNetworksStore } from '@/stores/networks'; import { useVirtualIPsStore } from '@/stores/virtualips'; import { useLoadBalancersStore } from '@/stores/loadbalancers'; import { usePrefixesStore } from '@/stores/prefixes'
const ui=useUIStore(),ns=useNamespaceStore(),machines=useMachinesStore(),volumes=useVolumesStore(),networks=useNetworksStore(),vips=useVirtualIPsStore(),lbs=useLoadBalancersStore(),prefixes=usePrefixesStore()
const connectionCopy=computed(()=>({checking:'check in progress',connected:'connected',disconnected:'unavailable'}[ui.connectionState]))
const summaries=computed(()=>[{label:'Machines',count:machines.items.length,to:'/machines',icon:'mdi-server-outline'},{label:'Volumes',count:volumes.items.length,to:'/volumes',icon:'mdi-database-outline'},{label:'Networks',count:networks.items.length,to:'/networks',icon:'mdi-lan'},{label:'Virtual IPs',count:vips.items.length,to:'/virtualips',icon:'mdi-earth'},{label:'Load Balancers',count:lbs.items.length,to:'/loadbalancers',icon:'mdi-scale-balance'},{label:'IP Prefixes',count:prefixes.items.length,to:'/prefixes',icon:'mdi-ip-network-outline'}])
const resources=computed(()=>[...machines.items.map(x=>({name:x.name,kind:'Machine',status:x.state,createdAt:x.createdAt,to:`/machines/${x.name}`,icon:'mdi-server-outline'})),...volumes.items.map(x=>({name:x.name,kind:'Volume',status:x.state,createdAt:x.createdAt,to:`/volumes/${x.name}`,icon:'mdi-database-outline'})),...networks.items.map(x=>({name:x.name,kind:'Network',status:x.state,createdAt:x.createdAt,to:`/networks/${x.name}`,icon:'mdi-lan'})),...prefixes.items.map(x=>({name:x.name,kind:'IP Prefix',status:x.phase,createdAt:x.createdAt,to:`/prefixes/${x.name}`,icon:'mdi-ip-network-outline'}))])
const attention=computed(()=>resources.value.filter(x=>['warning','error'].includes(classifyStatus(x.status))))
const pending=computed(()=>resources.value.filter(x=>classifyStatus(x.status)==='pending'))
const recent=computed(()=>resources.value.filter(x=>x.createdAt).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,8))
</script>
<style scoped>.health-strip{display:grid;grid-template-columns:2fr repeat(3,1fr);gap:16px}.health-strip>div{display:flex;flex-direction:column}.health-strip span{font-size:12px;opacity:.75}.summary-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}.summary{display:grid;grid-template-columns:auto 1fr;gap:4px 10px;padding:16px;border:1px solid var(--ic-border);border-radius:var(--ic-radius-md);background:var(--ic-surface);color:var(--ic-text);text-decoration:none}.summary strong{grid-column:2;font-size:22px}@media(max-width:960px){.summary-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:600px){.health-strip{grid-template-columns:1fr 1fr}.summary-grid{grid-template-columns:repeat(2,1fr)}}</style>
